52	    private String city;
53	
54	    @Column(name = "postcode")
55	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
56	    private String postcode;
57	
58	    @Column(name = "telephone")
59	    @NotEmpty
60	    @Pattern(regexp = "^\\+[0-9]{8,15}$",
61	            message = "Phone number must be E.164: '+' followed by 8 to 15 digits")
62	    private String telephone;
63	
64	    @Column(name = "email")
65	    private String email;
66	
67	    @Column(name = "title")
68	    private String title;
69	
