79	    @Column(name = "membership_number")
80	    private String membershipNumber;
81	
82	    @Column(name = "household_id")
83	    private String householdId;
84	
85	    @Column(name = "namesake_count")
86	    private Integer namesakeCount;
87	
88	    @Column(name = "possible_duplicate")
89	    private Boolean possibleDuplicate;
