97	    @Transient
98	    private Integer householdSize;
99	
100	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
101	    private Set<Pet> pets;
102	
103	    public String getAddress() {
104	        return this.address;
105	    }
106	
107	    public void setAddress(String address) {
108	        this.address = address;
109	    }
110	
111	    public String getAddressLine1() {
112	        return this.addressLine1;
113	    }
114	
115	    public void setAddressLine1(String addressLine1) {
116	        this.addressLine1 = addressLine1;
117	    }
118	
119	    public String getAddressLine2() {
120	        return this.addressLine2;
121	    }
122	
123	    public void setAddressLine2(String addressLine2) {
124	        this.addressLine2 = addressLine2;
125	    }
126	
127	    public String getCity() {
128	        return this.city;
129	    }
130	
131	    public void setCity(String city) {
132	        this.city = city;
133	    }
134	
135	    public String getPostcode() {
136	        return this.postcode;
137	    }
138	
139	    public void setPostcode(String postcode) {
140	        this.postcode = postcode;
141	    }
142	
143	    public String getTelephone() {
144	        return this.telephone;
145	    }
146	
147	    public void setTelephone(String telephone) {
148	        this.telephone = telephone;
149	    }
150	
151	    public String getEmail() {
152	        return this.email;
153	    }
154	
155	    public void setEmail(String email) {
156	        this.email = email;
157	    }
158	
159	    public String getTitle() {
160	        return this.title;
161	    }
162	
163	    public void setTitle(String title) {
164	        this.title = title;
165	    }
166	
167	    /**
168	     * The owner's salutation, derived at response time from the optional {@link #title} and the
169	     * {@link #getLastName() lastName}: the title, a single space, then the lastName (e.g.
170	     * {@code DR Who}) when a title is present, otherwise just the lastName. Not persisted as a
171	     * separate value; composed from the stored title and last name.
172	     */
173	    public String getSalutation() {
174	        if (this.title == null || this.title.isBlank()) {
175	            return getLastName();
176	        }
177	        return this.title + " " + getLastName();
178	    }
179	
180	    public LocalDate getRegistrationDate() {
181	        return this.registrationDate;
182	    }
183	
184	    public void setRegistrationDate(LocalDate registrationDate) {
185	        this.registrationDate = registrationDate;
186	    }
187	
188	    public LocalDate getBirthDate() {
189	        return this.birthDate;
190	    }
191	
192	    public void setBirthDate(LocalDate birthDate) {
193	        this.birthDate = birthDate;
194	    }
195	
196	    /**
197	     * The owner's age band, derived at response time from {@link #birthDate} against
198	     * {@link #registrationDate}: {@code MINOR} when under 18 years old, {@code ADULT} when 18 to 64,
199	     * and {@code SENIOR} when 65 or over. {@code null} when the owner has no birth date (or no
200	     * registration date to compute against). Not persisted.
201	     */
202	    public String getAgeBand() {
203	        if (this.birthDate == null || this.registrationDate == null) {
204	            return null;
205	        }
206	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
207	        if (age < 18) {
208	            return "MINOR";
209	        }
210	        if (age < 65) {
211	            return "ADULT";
212	        }
213	        return "SENIOR";
214	    }
215	
216	    public String getCustomerCode() {
217	        return this.customerCode;
218	    }
219	
220	    public void setCustomerCode(String customerCode) {
221	        this.customerCode = customerCode;
222	    }
223	
224	    public String getMembershipNumber() {
225	        return this.membershipNumber;
226	    }
227	
228	    public void setMembershipNumber(String membershipNumber) {
229	        this.membershipNumber = membershipNumber;
230	    }
231	
232	    public String getHouseholdId() {
233	        return this.householdId;
234	    }
235	
236	    public void setHouseholdId(String householdId) {
237	        this.householdId = householdId;
238	    }
239	
240	    public Integer getNamesakeCount() {
241	        return this.namesakeCount;
242	    }
243	
244	    public void setNamesakeCount(Integer namesakeCount) {
245	        this.namesakeCount = namesakeCount;
246	    }
