248	    /**
249	     * Whether this owner, when created, was a possible (soft) duplicate of an earlier owner, keyed
250	     * off the shared {@link #getHouseholdId() householdId} (same lastName and postcode). A declared
251	     * household member (created with {@code sharesHousehold} true) is never flagged; any other owner
252	     * joining an existing household is rejected 409 instead. {@code false} when no such earlier owner
253	     * existed. Assigned at creation.
254	     */
255	    public Boolean getPossibleDuplicate() {
256	        return this.possibleDuplicate;
257	    }
258	
259	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
260	        this.possibleDuplicate = possibleDuplicate;
261	    }
262	
263	    /**
264	     * The id of the earlier owner this owner is a possible duplicate of (the earliest such match),
265	     * or {@code null} when {@link #getPossibleDuplicate()} is false. Assigned at creation.
266	     */
267	    public Integer getPossibleDuplicateOf() {
268	        return this.possibleDuplicateOf;
269	    }
270	
271	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
272	        this.possibleDuplicateOf = possibleDuplicateOf;
273	    }
274	
275	    /**
276	     * Whether more than 80 owners had already been created on this owner's registration day,
277	     * derived at response time and not persisted. {@code true} triggers a bulk-signup warning
278	     * in the response.
279	     */
280	    public Boolean getBulkSignupWarning() {
281	        return this.bulkSignupWarning;
282	    }
283	
284	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
285	        this.bulkSignupWarning = bulkSignupWarning;
286	    }
287	
288	    /**
289	     * The number of owners in this owner's household (owners sharing the same
290	     * {@link #householdId}), derived at response time and not persisted.
291	     */
292	    public Integer getHouseholdSize() {
293	        return this.householdSize;
294	    }
295	
296	    public void setHouseholdSize(Integer householdSize) {
297	        this.householdSize = householdSize;
298	    }
299	
300	    /**
301	     * The owner's membership points, derived at response time. Starts at {@code 0}, plus 2 when an
302	     * email is present, plus 1 when {@link #namesakeCount} is 0, plus 2 when the
303	     * {@link #getHouseholdSize() household} has 3 or more members, plus 3 when tenure exceeds 365 days
304	     * (measured from the {@link #registrationDate}).
305	     */
306	    public Integer getMembershipPoints() {
307	        int points = 0;
308	        if (this.email != null && !this.email.isEmpty()) {
309	            points += 2;
310	        }
311	        if (this.namesakeCount != null && this.namesakeCount == 0) {
312	            points += 1;
313	        }
314	        if (this.householdSize != null && this.householdSize >= 3) {
315	            points += 2;
316	        }
317	        if (getTenureDays() > 365) {
318	            points += 3;
319	        }
320	        return points;
321	    }
322	
323	    /**
324	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints() membershipPoints}:
325	     * {@code 1} for 0-1 points, {@code 2} for 2-3 points, {@code 3} for 4-5 points, and {@code 4} for
326	     * 6 or more points.
327	     */
328	    public Integer getMembershipLevel() {
329	        int points = getMembershipPoints();
330	        if (points <= 1) {
331	            return 1;
332	        }
333	        if (points <= 3) {
334	            return 2;
335	        }
336	        if (points <= 5) {
337	            return 3;
338	        }
339	        return 4;
340	    }
341	
342	    /**
343	     * The owner's tenure in whole days, measured from the {@link #registrationDate} to today; zero
344	     * when the registration date is absent or in the future.
345	     */
346	    private long getTenureDays() {
347	        if (this.registrationDate == null) {
348	            return 0;
349	        }
350	        long days = ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
351	        return Math.max(days, 0);
352	    }
353	
354	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
355	    private static final Map<String, String> CITY_REGION = Map.of(
356	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
357	
358	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive {@link #getLocality()}. */
359	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
360	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
361	
362	    /** Fixed region-to-IANA-timezone table used to derive {@link #getTimezone()}. */
363	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
364	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
365	
366	    /**
367	     * The fixed city-to-region mapping ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
368	     * {@code Brisbane -> QLD}): the region for {@code city}, or {@code null} when the city is not in
369	     * the table. Used only by postcode validation, which branches on "known region or not" by testing
370	     * for {@code null} before range-checking the postcode.
371	     */
372	    public static String regionOf(String city) {
373	        return CITY_REGION.get(city);
374	    }
375	
376	    /**
377	     * The region whose fixed postcode range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
378	     * {@code QLD 4000-4099}) contains {@code postcode}, or {@code null} when {@code postcode} is
379	     * absent, not a 4-digit number, or in no known range.
380	     */
381	    public static String regionOfPostcode(String postcode) {
382	        if (postcode == null || postcode.isEmpty()) {
383	            return null;
384	        }
385	        int value;
386	        try {
387	            value = Integer.parseInt(postcode);
388	        } catch (NumberFormatException ex) {
389	            return null;
390	        }
391	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
392	            int[] range = entry.getValue();
393	            if (value >= range[0] && value <= range[1]) {
394	                return entry.getKey();
395	            }
396	        }
397	        return null;
398	    }
399	
400	    /**
401	     * The owner's region, derived at response time from the {@code REGION} prefix of the
402	     * {@link #customerCode} (the segment before the first {@code '-'}). Because the customer code is
403	     * assigned as {@code <REGION>-<HASH8>} with REGION taken from the postcode, the locality follows
404	     * the same region-and-hash identity as the customer code. {@code UNKNOWN} when the owner has no
405	     * customer code.
406	     */
407	    public String getLocality() {
408	        if (this.customerCode == null) {
409	            return "UNKNOWN";
410	        }
411	        int dash = this.customerCode.indexOf('-');
412	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
413	    }
414	
415	    /**
416	     * The owner's IANA timezone name, derived at response time from the {@link #getLocality()
417	     * locality}/region via the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
418	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null}
419	     * when the region is not in the table. Not persisted.
420	     */
421	    public String getTimezone() {
422	        return REGION_TIMEZONE.get(getLocality());
423	    }
424	
425	    /**
426	     * The owner's preferred contact channel, derived at response time: {@code EMAIL} when an
427	     * email is present, otherwise {@code PHONE}. Not persisted.
428	     */
429	    public String getContactPreference() {
430	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
431	    }
432	
433	    /**
434	     * A single Luhn check digit (0-9) derived at response time over the digits contained in
435	     * {@link #customerCode} (non-digit characters are ignored), or {@code null} when the owner
436	     * has no customer code. Computed with the standard Luhn algorithm — doubling every second
437	     * digit from the right, subtracting 9 from any result over 9, and taking
438	     * {@code (10 - sum % 10) % 10}. Not persisted.
439	     */
440	    public Integer getCheckDigit() {
441	        if (this.customerCode == null) {
442	            return null;
443	        }
444	        int sum = 0;
445	        boolean dbl = true;
446	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
447	            char c = this.customerCode.charAt(i);
448	            if (c < '0' || c > '9') {
449	                continue;
450	            }
451	            int d = c - '0';
452	            if (dbl) {
453	                d *= 2;
454	                if (d > 9) {
455	                    d -= 9;
456	                }
457	            }
458	            sum += d;
459	            dbl = !dbl;
460	        }
461	        return (10 - (sum % 10)) % 10;
462	    }
463	
464	    /**
465	     * A display-only derived string composing the owner's canonical contact and household values:
466	     * {@code normalizedTelephone|email|householdId}, joined with '|'. The telephone is stored in
467	     * canonical E.164 form and the email lower-cased; an absent email or householdId contributes an
468	     * empty segment. Derived at response time and exposed as a read-only response field only — it
469	     * drives no check. Duplicate detection is purely household-based (see
470	     * {@code CheckOwnerHouseholdUnique}, which compares {@link #getHouseholdId() householdId}); this
471	     * key is not consulted. Not persisted.
472	     */
473	    public String getIdentityKey() {
474	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
475	    }
476	
477	    private static String keyPart(String value) {
478	        return value == null ? "" : value;
479	    }
480	
481	    /**
482	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
483	     * national digits (everything after the country code) grouped in threes and space-separated —
484	     * e.g. {@code +61412345678} becomes {@code +61 412 345 678}. The country code is recognised for
485	     * '+61' (2 digits) and '+1' (1 digit); any other prefix falls back to a 2-digit country code.
486	     * {@code null} when the telephone is absent or not a valid E.164 value. Derived at response time
487	     * and not persisted; the raw {@link #getTelephone() telephone} stays in E.164 form.
488	     */
489	    public String getTelephoneDisplay() {
490	        if (this.telephone == null || !this.telephone.matches("\\+\\d{8,15}")) {
491	            return null;
492	        }
493	        String digits = this.telephone.substring(1);
494	        int countryCodeLength;
495	        if (digits.startsWith("61")) {
496	            countryCodeLength = 2;
497	        }
498	        else if (digits.startsWith("1")) {
499	            countryCodeLength = 1;
500	        }
501	        else {
502	            countryCodeLength = 2;
503	        }
504	        String countryCode = digits.substring(0, countryCodeLength);
505	        String national = digits.substring(countryCodeLength);
506	        StringBuilder display = new StringBuilder("+").append(countryCode);
507	        for (int i = 0; i < national.length(); i += 3) {
508	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
509	        }
510	        return display.toString();
511	    }
512	
513	    protected Set<Pet> getPetsInternal() {
514	        if (this.pets == null) {
515	            this.pets = new HashSet<>();
516	        }
517	        return this.pets;
518	    }
519	
520	    protected void setPetsInternal(Set<Pet> pets) {
521	        this.pets = pets;
522	    }
523	
524	    public List<Pet> getPets() {
525	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
526	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
527	        return Collections.unmodifiableList(sortedPets);
528	    }
529	
530	    public void setPets(List<Pet> pets) {
531	        this.pets = new HashSet<>(pets);
532	    }
533	
534	    public void addPet(Pet pet) {
535	        getPetsInternal().add(pet);
536	        pet.setOwner(this);
537	    }
538	
539	    /**
540	     * Return the Pet with the given name, or null if none found for this Owner.
541	     *
542	     * @param name to test
543	     * @return true if pet name is already in use
544	     */
545	    public Pet getPet(String name) {
546	        return getPet(name, false);
547	    }
548	
549	    /**
550	     * Return the Pet with the given name, or null if none found for this Owner.
551	     *
552	     * @param name to test
553	     * @return true if pet name is already in use
554	     */
555	    public Pet getPet(String name, boolean ignoreNew) {
556	        name = name.toLowerCase();
557	        for (Pet pet : getPetsInternal()) {
558	            if (!ignoreNew || !pet.isNew()) {
559	                String compName = pet.getName();
560	                compName = compName.toLowerCase();
561	                if (compName.equals(name)) {
562	                    return pet;
563	                }
564	            }
565	        }
566	        return null;
567	    }
568	
569	    public Pet getPet(Integer petId) {
570	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
571	    }
572	
573	    @Override
574	    public String toString() {
575	        return new ToStringCreator(this)
576	
577	            .append("id", this.getId())
578	            .append("new", this.isNew())
579	            .append("lastName", this.getLastName())
580	            .append("firstName", this.getFirstName())
581	            .append("address", this.address)
582	            .append("city", this.city)
583	            .append("telephone", this.telephone)
584	            .append("email", this.email)
585	            .toString();
586	    }
587	}
